), resolved AS (
  SELECT
    p.id AS personale_id,
    src.track_key,
    src.field_key,
    src.value_date,
    src.value_text
  FROM src
  JOIN public.personale p
    ON lower(regexp_replace(trim(p.full_name), '\s+', ' ', 'g')) =
       lower(regexp_replace(trim(src.full_name), '\s+', ' ', 'g'))
)
INSERT INTO public.formazione_rfi_records(
  personale_id, track_key, field_key, value_date, value_text, source_file
)
SELECT
  personale_id, track_key, field_key, value_date, value_text, 'aaa.xlsx'
FROM resolved
ON CONFLICT (personale_id, track_key, field_key)
DO UPDATE SET
  value_date = EXCLUDED.value_date,
  value_text = EXCLUDED.value_text,
  source_file = EXCLUDED.source_file,
  updated_at = now();